using BARANG.Core.Domain.Customers;
using BARANG.Core.Domain.Organization;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace BARANG.Core.Infrastructure.Persistence.Configurations;

internal static class CustomerConfiguration
{
    internal static void Base<T>(EntityTypeBuilder<T>b,string table)where T:class {b.ToTable(table,t=>t.HasCheckConstraint($"ck_{table}_version_positive","version > 0"));b.HasKey("Id");b.Property<Guid>("Id").HasColumnName("id").ValueGeneratedNever();b.Property<Guid>("CompanyId").HasColumnName("company_id");b.Property<DateTimeOffset>("CreatedAtUtc").HasColumnName("created_at_utc");b.Property<DateTimeOffset>("UpdatedAtUtc").HasColumnName("updated_at_utc");b.Property<long>("Version").HasColumnName("version").IsConcurrencyToken();}
    internal static void Owner<T>(EntityTypeBuilder<T>b)where T:class=>b.HasOne<Customer>().WithMany().HasForeignKey("CustomerId","CompanyId").HasPrincipalKey(nameof(Customer.Id),nameof(Customer.CompanyId)).OnDelete(DeleteBehavior.Restrict);
}

internal sealed class CustomerEntityConfiguration:IEntityTypeConfiguration<Customer>
{
    public void Configure(EntityTypeBuilder<Customer>b)
    {
        CustomerConfiguration.Base(b,"customers");b.HasKey(x=>x.Id).HasName("pk_customers");b.HasAlternateKey(x=>new{x.Id,x.CompanyId}).HasName("ak_customers_id_company_id");b.Ignore(x=>x.IsActive);
        b.Property(x=>x.CustomerCode).HasColumnName("customer_code").HasMaxLength(50);b.Property(x=>x.CustomerType).HasColumnName("customer_type").HasConversion(v=>v==CustomerType.LegalEntity?"Legal":"Individual",v=>v=="Legal"||v=="LegalEntity"?CustomerType.LegalEntity:CustomerType.Individual).HasMaxLength(20);b.Property(x=>x.DisplayName).HasColumnName("display_name").HasMaxLength(200);b.Property(x=>x.Status).HasColumnName("status_code").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.PrimaryMobile).HasColumnName("primary_mobile").HasMaxLength(16);b.Property(x=>x.PrimaryPhone).HasColumnName("primary_phone").HasMaxLength(16);b.Property(x=>x.PrimaryEmail).HasColumnName("primary_email").HasMaxLength(320);b.Property(x=>x.EconomicCode).HasColumnName("economic_code").HasMaxLength(64);b.Property(x=>x.CustomerGroupCode).HasColumnName("customer_group_code").HasMaxLength(80);b.Property(x=>x.CustomerGroupId).HasColumnName("customer_group_id");b.Property(x=>x.PriceGroupCode).HasColumnName("price_group_code").HasMaxLength(80);b.Property(x=>x.PriceGroupId).HasColumnName("price_group_id");b.Property(x=>x.SalesRepresentativePersonId).HasColumnName("sales_representative_person_id");b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(2000);
        b.HasOne<Company>().WithMany().HasForeignKey(x=>x.CompanyId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_customers_companies_company_id");b.HasOne<Person>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.SalesRepresentativePersonId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_customers_sales_representative_company_person");
        b.HasIndex(x=>new{x.CompanyId,x.CustomerCode}).IsUnique().HasDatabaseName("uq_customers_company_code");b.HasIndex(x=>new{x.CompanyId,x.Status,x.CustomerCode}).HasDatabaseName("ix_customers_directory");b.HasIndex(x=>new{x.CompanyId,x.DisplayName}).HasDatabaseName("ix_customers_company_display_name");b.HasIndex(x=>new{x.CompanyId,x.PrimaryMobile}).HasDatabaseName("ix_customers_company_mobile");b.HasIndex(x=>new{x.CompanyId,x.PrimaryEmail}).HasDatabaseName("ix_customers_company_email");b.HasIndex(x=>new{x.CompanyId,x.EconomicCode}).HasFilter("economic_code IS NOT NULL").HasDatabaseName("ix_customers_company_economic_code");
    }
}

internal sealed class IndividualCustomerProfileConfiguration:IEntityTypeConfiguration<IndividualCustomerProfile>
{
    public void Configure(EntityTypeBuilder<IndividualCustomerProfile>b){CustomerConfiguration.Base(b,"individual_customer_profiles");b.Property(x=>x.CustomerId).HasColumnName("customer_id");b.Property(x=>x.FirstName).HasColumnName("first_name").HasMaxLength(100);b.Property(x=>x.LastName).HasColumnName("last_name").HasMaxLength(100);b.Property(x=>x.NationalId).HasColumnName("national_id").HasMaxLength(64);b.Property(x=>x.FatherName).HasColumnName("father_name").HasMaxLength(100);b.Property(x=>x.BirthDate).HasColumnName("birth_date");b.Property(x=>x.GenderCode).HasColumnName("gender_code").HasMaxLength(80);b.Property(x=>x.BirthCertificateNumber).HasColumnName("birth_certificate_number").HasMaxLength(64);b.Property(x=>x.PlaceOfIssue).HasColumnName("place_of_issue").HasMaxLength(150);b.Property(x=>x.Occupation).HasColumnName("occupation").HasMaxLength(150);CustomerConfiguration.Owner(b);b.HasIndex(x=>new{x.CompanyId,x.CustomerId}).IsUnique();b.HasIndex(x=>new{x.CompanyId,x.NationalId}).HasFilter("national_id IS NOT NULL").IsUnique();b.HasIndex(x=>new{x.CompanyId,x.LastName,x.FirstName});}
}

internal sealed class LegalCustomerProfileConfiguration:IEntityTypeConfiguration<LegalCustomerProfile>
{
    public void Configure(EntityTypeBuilder<LegalCustomerProfile>b){CustomerConfiguration.Base(b,"legal_customer_profiles");b.Property(x=>x.CustomerId).HasColumnName("customer_id");b.Property(x=>x.LegalName).HasColumnName("legal_name").HasMaxLength(200);b.Property(x=>x.TradeName).HasColumnName("trade_name").HasMaxLength(200);b.Property(x=>x.NationalId).HasColumnName("national_id").HasMaxLength(64);b.Property(x=>x.RegistrationNumber).HasColumnName("registration_number").HasMaxLength(64);b.Property(x=>x.EstablishmentDate).HasColumnName("establishment_date");b.Property(x=>x.LegalEntityTypeCode).HasColumnName("legal_entity_type_code").HasMaxLength(80);b.Property(x=>x.LegalEntityTypeId).HasColumnName("legal_entity_type_id");b.Property(x=>x.BusinessActivity).HasColumnName("business_activity").HasMaxLength(500);b.Property(x=>x.Website).HasColumnName("website").HasMaxLength(500);b.Property(x=>x.ManagingDirector).HasColumnName("managing_director").HasMaxLength(200);CustomerConfiguration.Owner(b);b.HasIndex(x=>new{x.CompanyId,x.CustomerId}).IsUnique();b.HasIndex(x=>new{x.CompanyId,x.NationalId}).HasFilter("national_id IS NOT NULL").IsUnique();b.HasIndex(x=>new{x.CompanyId,x.RegistrationNumber}).HasFilter("registration_number IS NOT NULL").IsUnique();b.HasIndex(x=>new{x.CompanyId,x.LegalName});}
}

internal sealed class CustomerContactConfiguration:IEntityTypeConfiguration<CustomerContact>
{
    public void Configure(EntityTypeBuilder<CustomerContact>b){CustomerConfiguration.Base(b,"customer_contacts");b.HasKey(x=>x.Id).HasName("pk_customer_contacts");b.Property(x=>x.CustomerId).HasColumnName("customer_id");b.Property(x=>x.ContactTypeCode).HasColumnName("contact_type_code").HasMaxLength(50);b.Property(x=>x.ContactRoleId).HasColumnName("contact_role_id");b.Property(x=>x.FirstName).HasColumnName("first_name").HasMaxLength(100);b.Property(x=>x.LastName).HasColumnName("last_name").HasMaxLength(100);b.Property(x=>x.Mobile).HasColumnName("mobile").HasMaxLength(16);b.Property(x=>x.Phone).HasColumnName("phone").HasMaxLength(16);b.Property(x=>x.Email).HasColumnName("email").HasMaxLength(320);b.Property(x=>x.PositionTitle).HasColumnName("position_title").HasMaxLength(150);b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(1000);b.Property(x=>x.IsPrimary).HasColumnName("is_primary");b.Property(x=>x.IsActive).HasColumnName("is_active");b.Property(x=>x.DisplayOrder).HasColumnName("display_order");CustomerConfiguration.Owner(b);b.HasIndex(x=>new{x.CompanyId,x.CustomerId,x.DisplayOrder,x.Id}).HasDatabaseName("ix_customer_contacts_customer_order");b.HasIndex(x=>new{x.CustomerId,x.IsPrimary}).HasFilter("is_primary AND is_active").IsUnique().HasDatabaseName("uq_customer_contacts_one_active_primary");}
