    public void Configure(EntityTypeBuilder<CustomerAddress>b){CustomerConfiguration.Base(b,"customer_addresses");b.HasKey(x=>x.Id).HasName("pk_customer_addresses");b.Ignore(x=>x.IsPrimary);b.Property(x=>x.CustomerId).HasColumnName("customer_id");b.Property(x=>x.AddressTypeCode).HasColumnName("address_type_code").HasMaxLength(50);b.Property(x=>x.AddressTypeId).HasColumnName("address_type_id");b.Property(x=>x.Title).HasColumnName("title").HasMaxLength(100);b.Property(x=>x.CountryCode).HasColumnName("country_code").HasMaxLength(2);b.Property(x=>x.ProvinceCode).HasColumnName("province_code").HasMaxLength(80);b.Property(x=>x.CityCode).HasColumnName("city_code").HasMaxLength(80);b.Property(x=>x.District).HasColumnName("district").HasMaxLength(150);b.Property(x=>x.AddressLine1).HasColumnName("address_line1").HasMaxLength(500);b.Property(x=>x.AddressLine2).HasColumnName("address_line2").HasMaxLength(500);b.Property(x=>x.PostalCode).HasColumnName("postal_code").HasMaxLength(32);b.Property(x=>x.RecipientName).HasColumnName("recipient_name").HasMaxLength(200);b.Property(x=>x.RecipientPhone).HasColumnName("recipient_phone").HasMaxLength(16);b.Property(x=>x.RecipientMobile).HasColumnName("recipient_mobile").HasMaxLength(16);b.Property(x=>x.Email).HasColumnName("email").HasMaxLength(254);b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(1000);b.Property(x=>x.IsDefault).HasColumnName("is_default");b.Property(x=>x.IsActive).HasColumnName("is_active");b.Property(x=>x.DisplayOrder).HasColumnName("display_order");CustomerConfiguration.Owner(b);b.HasIndex(x=>new{x.CompanyId,x.CustomerId,x.DisplayOrder,x.Id}).HasDatabaseName("ix_customer_addresses_customer_order");b.HasIndex(x=>new{x.CustomerId,x.IsDefault}).HasFilter("is_default AND is_active").IsUnique().HasDatabaseName("uq_customer_addresses_one_active_default");}
