internal sealed class CustomerFinancialProfileConfiguration:IEntityTypeConfiguration<CustomerFinancialProfile>
{
    public void Configure(EntityTypeBuilder<CustomerFinancialProfile>b){CustomerConfiguration.Base(b,"customer_financial_profiles");b.ToTable("customer_financial_profiles",t=>{t.HasCheckConstraint("ck_customer_financial_profiles_version_positive","version > 0");t.HasCheckConstraint("ck_customer_financial_profiles_credit","credit_limit >= 0");t.HasCheckConstraint("ck_customer_financial_profiles_discount","default_discount_percent >= 0 AND default_discount_percent <= 100");});b.Property(x=>x.CustomerId).HasColumnName("customer_id");b.Property(x=>x.CreditLimit).HasColumnName("credit_limit").HasPrecision(18,2);b.Property(x=>x.PaymentTermCode).HasColumnName("payment_term_code").HasMaxLength(80);b.Property(x=>x.PaymentTermId).HasColumnName("payment_term_id");b.Property(x=>x.PaymentConditionCode).HasColumnName("payment_condition_code").HasMaxLength(80);b.Property(x=>x.PaymentConditionId).HasColumnName("payment_condition_id");b.Property(x=>x.PreferredPaymentMethodCode).HasColumnName("preferred_payment_method_code").HasMaxLength(80);b.Property(x=>x.PreferredPaymentMethodId).HasColumnName("preferred_payment_method_id");b.Property(x=>x.DefaultDiscountPercent).HasColumnName("default_discount_percent").HasPrecision(5,2);b.Property(x=>x.FinancialStatus).HasColumnName("financial_status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.TaxStatusCode).HasColumnName("tax_status_code").HasMaxLength(80);b.Property(x=>x.TaxStatusId).HasColumnName("tax_status_id");b.Property(x=>x.DefaultCurrencyCode).HasColumnName("default_currency_code").HasMaxLength(3).IsFixedLength();CustomerConfiguration.Owner(b);b.HasIndex(x=>new{x.CompanyId,x.CustomerId}).IsUnique();}
}

